import {CALCULATOR_PARAMETER_FIELDS,calcGet,calcSet,calculatorRulesFor} from './calculator-params.js';
import {todayString} from './age.js';
const caEsc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let caBundle=null;
const caRoot=document.createElement('section');caRoot.id='calculator-administration';document.querySelector('#reviews').after(caRoot);
const caHeaders=()=>({'Content-Type':'application/json',...(document.querySelector('#admin-token').value?{Authorization:'Bearer '+document.querySelector('#admin-token').value}:{})});
async function caLoad(){try{const response=await fetch('/api/calculator/rules',{cache:'no-store'});caBundle=await response.json();if(!response.ok||!caBundle?.parameters)throw new Error('Nie udało się wczytać zasad kalkulatora.');const current=calculatorRulesFor(caBundle,todayString());caRoot.innerHTML=`<article><h2>Zintegrowany Kalkulator — parametry</h2><p>Wersja obowiązująca dziś: ${caEsc(current.appliedVersion)}. Zmiana jest osobną wersją z datą obowiązywania. Zapisane scenariusze zachowują dawną wersję do ponownego przeliczenia.</p><form id="calculator-rules-form"><label>Zmiana obowiązuje od<input type="date" name="effective" value="${todayString()}" required></label><div class="ca-parameters">${CALCULATOR_PARAMETER_FIELDS.map(([path,label,min,max])=>`<label>${caEsc(label)}<input data-ca-param="${path}" type="number" step="any" min="${min}" max="${max}" value="${calcGet(current.parameters,path)}" required></label>`).join('')}</div><details><summary>Wskaźniki roczne, waloryzacja i limity po ustaniu</summary><p>Uzupełniaj wyłącznie po sprawdzeniu urzędowego wskaźnika. Limity po ustaniu: tablica obiektów z from, to i amount; brak zweryfikowanej kwoty blokuje jej zgadywanie.</p><label>Minimalne wynagrodzenie według roku<textarea name="minimumWage">${caEsc(JSON.stringify(current.parameters.minimumWage,null,2))}</textarea></label><label>Prognozowane przeciętne wynagrodzenie według roku<textarea name="forecastWage">${caEsc(JSON.stringify(current.parameters.forecastWage||{2026:current.parameters.business.forecast2026},null,2))}</textarea></label><label>Waloryzacja rehabilitacyjnego według pierwszego kwartału<textarea name="rehabIndex">${caEsc(JSON.stringify(current.parameters.rehabIndex,null,2))}</textarea></label><label>Limity podstawy po ustaniu ubezpieczenia<textarea name="postInsuranceCap">${caEsc(JSON.stringify(current.parameters.postInsuranceCap,null,2))}</textarea></label></details><label>Osoba odpowiedzialna za weryfikację<input name="reviewer" maxlength="200" required></label><label>Podstawa prawna<textarea name="legalBasis" maxlength="2000" required></textarea></label><label>Oficjalny adres źródła<input name="sourceUrl" type="url" required></label><label>Przepisy przejściowe i prawa nabyte<textarea name="transitionNote" maxlength="2000" required></textarea></label><label>Uzasadnienie i źródło zmiany<textarea name="note" maxlength="1000" required></textarea></label><label><input name="verified" type="checkbox" style="width:auto;min-height:0" required> Zweryfikowano oficjalną podstawę, wartości, datę obowiązywania i wpływ na obliczenia.</label><button class="primary" type="submit">Zapisz wersję zasad kalkulatora</button><p id="ca-status" role="status"></p></form><details><summary>Historia i przyszłe wersje (${caBundle.versions.length})</summary>${caBundle.versions.map(v=>`<p>${caEsc(v.id)} · od ${caEsc(v.validFrom)} · ${caEsc(v.note||'')}</p>`).join('')||'<p>Brak dodatkowych wersji.</p>'}</details></article>`;
    caRoot.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,status=caRoot.querySelector('#ca-status');try{const parameters=structuredClone(current.parameters);caRoot.querySelectorAll('[data-ca-param]').forEach(input=>calcSet(parameters,input.dataset.caParam,Number(input.value)));for(const key of ['minimumWage','forecastWage','rehabIndex','postInsuranceCap'])parameters[key]=JSON.parse(form.elements[key].value);const r=await fetch('/api/calculator/rules',{method:'POST',headers:caHeaders(),body:JSON.stringify({parameters,validFrom:form.elements.effective.value,previousRevision:caBundle.revision,reviewer:form.elements.reviewer.value,legalBasis:form.elements.legalBasis.value,sourceUrl:form.elements.sourceUrl.value,transitionNote:form.elements.transitionNote.value,verified:form.elements.verified.checked,note:form.elements.note.value})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Nie udało się zapisać.');await caLoad();caRoot.querySelector('#ca-status').textContent='Zapisano nową wersję zasad. Obliczenia użyją jej od wskazanej daty.';}catch(error){status.textContent=error.message;}};
  }catch(e){caRoot.innerHTML='<article><h2>Parametry kalkulatora</h2><p>'+caEsc(e.message)+'</p></article>';}}
document.querySelector('#reload').addEventListener('click',caLoad);caLoad();
